sealed trait Msg
case object Increment extends Msg

final case class Model(count: Int = 0)

def update(msg: Msg, model: Model): Model = msg match {
  case Increment => model.copy(count = model.count + 1)
}

def view(model: Model): Html[Msg] =
  button(onClick(Increment))(s"count: ${model.count}")
// TyrianApp wires update/view and dispatches Msg through the runtime
